package main

// Expectations come from the existing AWS overlay/SQL contract tests and the
// Kubernetes operator contract, not from snapshots generated by this port.
import (
	"bytes"
	"context"
	"errors"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"reflect"
	"strings"
	"sync"
	"testing"

	"go.yaml.in/yaml/v3"
)

var toolOnce sync.Once
var testToolPath string
var testToolError error

func buildTool(t *testing.T) string {
	t.Helper()
	toolOnce.Do(func() {
		root, err := repositoryRoot()
		if err != nil {
			testToolError = err
			return
		}
		testToolPath = filepath.Join(root, ".tools/bin/aws")
		if err := os.MkdirAll(filepath.Dir(testToolPath), 0700); err != nil {
			testToolError = err
			return
		}
		cmd := exec.Command("go", "build", "-mod=readonly", "-o", testToolPath, "./aws")
		cmd.Dir = filepath.Join(root, "scripts")
		cmd.Env = append(os.Environ(), "GOWORK=off")
		output, err := cmd.CombinedOutput()
		if err != nil {
			testToolError = errors.New(string(output))
			return
		}
	})
	if testToolError != nil {
		t.Fatal(testToolError)
	}
	return testToolPath
}

